import numpy as np
def tryw(w, mode):
    base=[np.ones_like(t),x,v,v*np.cos(w*t),v*np.sin(w*t),np.cos(w*t),np.sin(w*t)]
    if mode=='harm': base+=[np.cos(2*w*t),np.sin(2*w*t),np.cos(3*w*t),np.sin(3*w*t)]
    if mode=='chirp': base=[np.ones_like(t),x,v,v*np.cos(w*t*t),v*np.sin(w*t*t),np.cos(w*t*t),np.sin(w*t*t)]
    if mode=='sqrt': base=[np.ones_like(t),x,v,v*np.cos(w*np.sqrt(t)),v*np.sin(w*np.sqrt(t)),np.cos(w*np.sqrt(t)),np.sin(w*np.sqrt(t))]
    A=np.column_stack(base); c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
    return np.mean((dv_dt-A@c)**2)/np.var(dv_dt)
for mode,grid in [('harm',np.linspace(0.2,0.5,301)),('chirp',np.linspace(0.01,0.3,291)),('sqrt',np.linspace(0.05,3,291))]:
